/* Evidence-based self-assessment. No claim of automated code review. */
state.projectEvidence=state.projectEvidence||{};
const PROJECT_CRITERIA={
 'capstone-own':['逐句理解关键业务代码','端到端追踪数据与执行流程','独立完成行为修改','复现并修复故障','回归测试与干净环境交付'],
 'capstone-repo':['固定版本并复现运行','准确解释模块职责与依赖','追踪调用链并解释关键函数','完成小改动与回归测试','报告证据清楚并标明局限']
};
function evidenceAssessment(p){const records=state.projectEvidence[p.id]||[];const scores=(PROJECT_CRITERIA[p.id]||[]).map((_,i)=>Number(records[i]?.score||0));const total=scores.reduce((a,b)=>a+b,0);const evidenced=scores.every((s,i)=>s>=2&&(records[i]?.evidence||'').trim().length>=20);return {total,passed:evidenced&&total>=12};}
const originalProjectRender=renderProject;
renderProject=function(id){originalProjectRender(id);const p=PROJECTS.find(x=>x.id===id);if(!p?.capstone)return;const records=state.projectEvidence[id]||[];const section=document.createElement('section');section.className='project-stage evidence-section';section.innerHTML=`<span class="eyebrow">GRADUATION · 证据式自评</span><h2>留下证据，再判断是否掌握</h2><p>每项至少 2 分，总分至少 12 / 15；每项证据至少写 20 个字符。这只检查记录是否完整，不能自动证明代码质量。</p>${PROJECT_CRITERIA[id].map((name,i)=>`<div class="evidence-item"><div class="evidence-title"><label for="score-${i}">${i+1}. ${esc(name)}</label><select id="score-${i}" data-score="${i}" aria-label="${esc(name)}评分">${['0 · 尚未完成','1 · 跟着答案完成','2 · 查资料后独立完成','3 · 能处理变式与边界'].map((s,j)=>`<option value="${j}" ${Number(records[i]?.score||0)===j?'selected':''}>${s}</option>`).join('')}</select></div><textarea data-evidence="${i}" aria-label="${esc(name)}证据" placeholder="记录文件与函数、固定提交、测试命令和结果，或报告位置。不要填入密钥与隐私。">${esc(records[i]?.evidence||'')}</textarea></div>`).join('')}<div class="evidence-result" id="evidence-result"></div><button class="primary" id="export-evidence">导出我的毕业验收记录 ↓</button>`;$('.project-detail').append(section);const read=()=>{state.projectEvidence[id]=PROJECT_CRITERIA[id].map((_,i)=>({score:Number($(`[data-score="${i}"]`).value),evidence:$(`[data-evidence="${i}"]`).value}));save();draw()};const draw=()=>{const a=evidenceAssessment(p);$('#evidence-result').textContent=`自评分 ${a.total} / 15 · ${a.passed?'记录达到自查门槛；仍需人工复核实际证据。':'继续补齐独立实践与证据，尚未达到自查门槛。'}`};section.querySelectorAll('select').forEach(e=>e.onchange=read);section.querySelectorAll('textarea').forEach(e=>e.oninput=read);draw();$('#export-evidence').onclick=()=>{const a=evidenceAssessment(p),records=state.projectEvidence[id]||[];download(id+'-evidence.md',`# ${p.title}\n\n自评 ${a.total}/15。此记录由学习者填写，未经自动或第三方代码审查。\n\n`+PROJECT_CRITERIA[id].map((name,i)=>`## ${i+1}. ${name}\n\n评分：${records[i]?.score||0}/3\n\n${records[i]?.evidence||'尚无证据'}\n`).join('\n'),'text/markdown')};};
if(location.hash.startsWith('#project/'))renderProject(location.hash.slice(9));
